import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import NavigationHeader from '../../components/navigation/NavigationHeader';
import AuthenticationGuard from '../../components/navigation/AuthenticationGuard';
import NotificationSystem from '../../components/navigation/NotificationSystem';
import BottomNavigation from '../../components/navigation/BottomNavigation';
import BookingFormHeader from './component/BookingFormHeader';
import BookingDetailsForm from './component/BookingDetailsForm';
import BookingPolicySection from './component/BookingPolicySection';
import BookingActions from './component/BookingActions';
import { listenBookings, createBooking } from '../../services/bookingService';
import { getBusinessSettings } from '../../services/settingsService';
import { auth } from '../../config/firebase';

const BookingForm = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [userName, setUserName] = useState('User');
  const [userRole, setUserRole] = useState('customer');

  const fieldData = location?.state?.fieldData || {
    id: 'field-001',
    name: 'Lapangan Futsal A',
    image: "https://images.unsplash.com/photo-1660848942601-4b7216b8a653",
    imageAlt: 'Modern indoor futsal field with green artificial turf, white boundary lines, and professional lighting system mounted on ceiling',
    location: 'Jl. Sudirman No. 123, Jakarta Pusat',
    capacity: '10-12 pemain',
    facilities: 'Ruang ganti, Toilet, Kantin, Parkir luas',
    pricePerHour: 150000
  };

  const [formData, setFormData] = useState({
    bookingDate: '',
    startTime: '',
    endTime: '',
    purpose: '',
    phoneNumber: '',
    specialRequirements: ''
  });
  const [businessSettings, setBusinessSettings] = useState({ weekdayHours:{ start:'08:00', end:'22:00' }, weekendHours:{ start:'06:00', end:'24:00' }, holidays:[] });
  const [bookings, setBookings] = useState([]);

  const [errors, setErrors] = useState({});

  useEffect(() => {
    const storedUserName = localStorage.getItem('userName') || 'User';
    const storedUserRole = localStorage.getItem('userRole') || 'customer';
    setUserName(storedUserName);
    setUserRole(storedUserRole);
    const unsubBookings = listenBookings((items)=> setBookings(items || []));
    (async ()=>{
      const res = await getBusinessSettings();
      if (res?.success && res?.data) setBusinessSettings(res?.data);
    })();
    return ()=> { if (unsubBookings) unsubBookings(); };
  }, []);

  const validateForm = () => {
    const newErrors = {};

    if (!formData?.bookingDate) {
      newErrors.bookingDate = 'Tanggal booking wajib diisi';
    } else {
      const selectedDate = new Date(formData.bookingDate);
      const today = new Date();
      today?.setHours(0, 0, 0, 0);
      if (selectedDate < today) {
        newErrors.bookingDate = 'Tanggal booking tidak boleh di masa lalu';
      }
    }

    if (!formData?.startTime) {
      newErrors.startTime = 'Waktu mulai wajib diisi';
    } else {
      try {
        const d = new Date(formData?.bookingDate);
        const day = d?.getDay();
        const isWeekend = day === 0 || day === 6;
        const hours = isWeekend ? (businessSettings?.weekendHours || { start:'06:00', end:'24:00' }) : (businessSettings?.weekdayHours || { start:'08:00', end:'22:00' });
        const [startH] = (hours?.start || '08:00')?.split(':')?.map(Number);
        const [endH] = (hours?.end || '22:00')?.split(':')?.map(Number);
        const [hSel] = formData?.startTime?.split(':')?.map(Number);
        if (hSel < startH || hSel >= endH) {
          newErrors.startTime = `Waktu operasional: ${hours?.start} - ${hours?.end} WIB`;
        }
      } catch(_) {}
    }

    if (!formData?.endTime) {
      newErrors.endTime = 'Waktu selesai wajib diisi';
    } else {
      try {
        const d = new Date(formData?.bookingDate);
        const day = d?.getDay();
        const isWeekend = day === 0 || day === 6;
        const hours = isWeekend ? (businessSettings?.weekendHours || { start:'06:00', end:'24:00' }) : (businessSettings?.weekdayHours || { start:'08:00', end:'22:00' });
        const [startH] = (hours?.start || '08:00')?.split(':')?.map(Number);
        const [endH] = (hours?.end || '22:00')?.split(':')?.map(Number);
        const [hStart] = formData?.startTime?.split(':')?.map(Number);
        const [hEnd] = formData?.endTime?.split(':')?.map(Number);
        if (hEnd <= hStart) {
          newErrors.endTime = 'Waktu selesai harus setelah waktu mulai';
        } else if (hEnd > endH || hEnd <= startH) {
          newErrors.endTime = `Waktu operasional: ${hours?.start} - ${hours?.end} WIB`;
        }
      } catch(_) {}
    }

    if (!formData?.purpose) {
      newErrors.purpose = 'Tujuan booking wajib dipilih';
    }

    if (!formData?.phoneNumber) {
      newErrors.phoneNumber = 'Nomor telepon wajib diisi';
    } else if (!/^[0-9]{10,13}$/?.test(formData?.phoneNumber)) {
      newErrors.phoneNumber = 'Format nomor telepon tidak valid (10-13 digit)';
    }

    if (formData?.specialRequirements && formData?.specialRequirements?.length > 500) {
      newErrors.specialRequirements = 'Catatan maksimal 500 karakter';
    }

    setErrors(newErrors);
    return Object.keys(newErrors)?.length === 0;
  };

  const handleInputChange = (e) => {
    const { name, value } = e?.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value
    }));

    if (errors?.[name]) {
      setErrors((prev) => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const isHoliday = (dateStr)=>{
    try {
      const iso = new Date(dateStr)?.toISOString()?.split('T')?.[0];
      return (businessSettings?.holidays || [])?.includes(iso);
    } catch(_) { return false; }
  };

  const handleSubmit = async () => {
    if (!validateForm()) {
      window.showNotification({
        type: 'error',
        message: 'Mohon lengkapi semua field yang wajib diisi'
      });
      return;
    }
    setIsSubmitting(true);
    try {
      const fieldId = fieldData?.id?.toString();
      const [newStartH] = formData?.startTime?.split(':')?.map(Number);
      const [newEndH] = formData?.endTime?.split(':')?.map(Number);
      const conflict = bookings?.some(b=> {
        if (b?.fieldId?.toString() !== fieldId) return false;
        if (b?.date !== formData?.bookingDate) return false;
        if (!(b?.status === 'pending' || b?.status === 'confirmed')) return false;
        const [exStartH] = String(b?.startTime || '00:00')?.split(':')?.map(Number);
        const [exEndHFromEnd] = String(b?.endTime || '')?.split(':')?.map(Number);
        const exDuration = Number(b?.duration || 1);
        const exEndH = Number.isFinite(exEndHFromEnd) && exEndHFromEnd > exStartH ? exEndHFromEnd : exStartH + exDuration;
        return newStartH < exEndH && newEndH > exStartH;
      });
      if (isHoliday(formData?.bookingDate)) {
        throw new Error('Tanggal yang dipilih adalah hari libur.');
      }
      if (conflict) {
        throw new Error('Slot waktu sudah terisi, pilih waktu lain.');
      }
      const bookingPayload = {
        userId: auth?.currentUser?.uid || localStorage.getItem('userId') || `guest-${Date.now()}`,
        userName: localStorage.getItem('userName') || 'Pengguna',
        fieldId: fieldData?.id,
        fieldName: fieldData?.name,
        date: formData?.bookingDate,
        startTime: formData?.startTime,
        endTime: formData?.endTime,
        duration: Math.max(1, (newEndH - newStartH)),
        purpose: formData?.purpose,
        phoneNumber: formData?.phoneNumber,
        specialRequests: formData?.specialRequirements,
        totalPrice: fieldData?.pricePerHour * Math.max(1, (newEndH - newStartH)) + 5000,
        status: 'pending'
      };
      const result = await createBooking(bookingPayload);
      if (result?.success) {
        const bookingId = result?.bookingId;
        window.showNotification({
          type: 'success',
          message: 'Booking berhasil dibuat'
        });
        navigate('/my-bookings');
      } else {
        window.showNotification({
          type: 'error',
          message: result?.error || 'Gagal membuat booking'
        });
        setIsSubmitting(false);
      }
    } catch (error) {
      window.showNotification({
        type: 'error',
        message: error?.message || 'Terjadi kesalahan saat memproses booking'
      });
      setIsSubmitting(false);
    }
  };

  const handleBack = () => {
    navigate('/field-schedule');
  };

  const handleLogout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('userRole');
    localStorage.removeItem('userName');
    navigate('/authentication');
  };

  const isFormValid = formData?.bookingDate &&
  formData?.startTime &&
  formData?.endTime &&
  formData?.purpose &&
  formData?.phoneNumber &&
  Object.keys(errors)?.length === 0;

  return (
    <AuthenticationGuard requiredRole="customer">
      <div className="min-h-screen bg-background">
        <NavigationHeader
          userRole={userRole}
          userName={userName}
          onLogout={handleLogout} />

        <NotificationSystem />

        <div className="pt-16 pb-20 md:pb-8">
          <BookingFormHeader onBack={handleBack} />

          <div className="container mx-auto px-4 py-8">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              <div className="lg:col-span-2 space-y-6">
              <div className="bg-card rounded-lg border border-border p-4">
                <div className="flex items-center space-x-4">
                  <img src={fieldData?.image} alt={fieldData?.imageAlt} className="w-20 h-20 rounded-lg object-cover" onError={(e)=>{e.target.src='/assets/images/no_image.png'}} />
                  <div className="flex-1">
                    <div className="text-lg font-semibold text-foreground">{fieldData?.name}</div>
                    <div className="text-sm text-muted-foreground">Harga per jam: Rp {fieldData?.pricePerHour?.toLocaleString('id-ID')}</div>
                    <div className="text-xs text-muted-foreground">Lokasi: {fieldData?.location}</div>
                  </div>
                </div>
              </div>

              
                <BookingDetailsForm
                  formData={formData}
                  errors={errors}
                  onChange={handleInputChange} />

                <BookingPolicySection />
              </div>

              <div className="lg:col-span-1">
                <div className="bg-card rounded-lg border border-border p-4">
                  <div className="space-y-2">
                    <div className="flex justify-between">
                      <span className="text-sm text-muted-foreground">Lapangan</span>
                      <span className="text-sm font-medium text-foreground">{fieldData?.name}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-sm text-muted-foreground">Tanggal</span>
                      <span className="text-sm font-medium text-foreground">{formData?.bookingDate || '-'}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-sm text-muted-foreground">Waktu</span>
                      <span className="text-sm font-medium text-foreground">{formData?.startTime || '-'}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-sm text-muted-foreground">Selesai</span>
                      <span className="text-sm font-medium text-foreground">{formData?.endTime || '-'}</span>
                    </div>
                    <div className="flex justify-between">
                      <span className="text-sm text-muted-foreground">Durasi</span>
                      <span className="text-sm font-medium text-foreground">{Math.max(0, ((formData?.endTime && formData?.startTime) ? (parseInt(formData?.endTime?.split(':')?.[0]) - parseInt(formData?.startTime?.split(':')?.[0])) : 0))} jam</span>
                    </div>
                    <div className="border-t border-border pt-3 mt-3">
                      <div className="flex justify-between">
                        <span className="text-base font-semibold text-foreground">Total</span>
                        <span className="text-base font-bold text-primary">Rp {(fieldData?.pricePerHour * Math.max(0, ((formData?.endTime && formData?.startTime) ? (parseInt(formData?.endTime?.split(':')?.[0]) - parseInt(formData?.startTime?.split(':')?.[0])) : 0)) + 5000)?.toLocaleString('id-ID')}</span>
                      </div>
                    </div>
                  </div>
                </div>

              </div>
            </div>

            <div className="mt-8">
              <BookingActions
                onSubmit={handleSubmit}
                onCancel={handleBack}
                isSubmitting={isSubmitting}
                isFormValid={isFormValid} />

            </div>
          </div>
        </div>

        <BottomNavigation userRole={userRole} />
      </div>
    </AuthenticationGuard>);

};

export default BookingForm;
